const q=(u,n,prompt,options,answer,why,concept)=>({id:`geo.a.c2.${u}.${n}`,prompt,options,answer,why,concept:'geo.a.coast.'+concept});
const make=(slug,title,refs,cards,tasks,practice,check,model)=>({id:'geography.a.coasts.'+slug,topicId:'geography.a.coasts',option:'coasts',title,refs,cards,tasks,practice,check,model,minutes:25});
export const coastalLessons2=[
make('deposition','Beaches, spits and bars',['1.4b','Integrated skill 7: introductory'],[
 ['When sediment stays','Deposition builds up material when transport conditions no longer carry some of the load. A beach is an accumulation of sand or shingle along a shore. Supply, wave conditions and losses interact: constructive conditions may add material, while storms can remove or redistribute it. A beach is not a solid rock platform.'],
 ['A spit reaches out','Longshore drift can carry sediment beyond a change in the coastline’s direction. Deposition may extend a ridge attached to land at one end: a spit. Changing wave directions can curve its tip. Sheltered water behind it can accumulate fine sediment, allowing saltmarsh to develop where conditions suit. River flow may keep an estuary mouth open.'],
 ['Across a bay','A bar can form where deposition extends across a bay and joins land at both ends, enclosing a lagoon. A spit does not inevitably become a bar: currents, depth, sediment supply and changing waves matter. Our plan views isolate shape and sediment movement; they are not maps or forecasts for a real coast.']
],[['Predict: a current loses the ability to carry some sand. The sand can…',['Be deposited','Turn instantly into chalk','Stop being affected by gravity'],0],['Compare spit and bar. A spit is attached to land…',['At one end','Always at both ends','At neither end by definition'],0],['Behind a sheltered spit, fine sediment may…',['Accumulate and support saltmarsh','Always move faster than offshore','Become a new granite intrusion'],0],['A river keeps flowing through an estuary mouth. This can…',['Prevent a spit closing the mouth completely','Guarantee every spit becomes a bar','Stop all coastal transport'],0]],
[q('dep','p1','Which is a deposit of loose sand or shingle?',['A beach','A wave-cut rock platform','A fault'],0,'A beach contains accumulated sediment; a platform is eroded rock.','deposition'),q('dep','p2','Longshore drift carries sediment beyond a bend in the coast. A ridge attached at one end may form a…',['Spit','Stack','Joint'],0,'Deposition beyond the bend can extend a spit.','spits'),q('dep','p3','What distinguishes a bay bar from this model’s spit?',['The bar joins land at both ends across a bay','The bar must be volcanic','The spit has no sediment'],0,'A bar may enclose a lagoon behind its ridge.','bars')],
[q('dep','c1','A beach changes because…',['Sediment inputs, transport and losses interact','Its grains are fixed permanently','Only rock colour matters'],0,'Sediment balances change with wave and supply conditions.','deposition'),q('dep','c2','A curved spit tip can reflect…',['Changing wave approaches','A guarantee of no waves','Only fresh lava'],0,'Changing transport directions can alter the tip.','spits'),q('dep','c3','A bar closes a bay. The water body behind it can become a…',['Lagoon','Headland','Fault'],0,'A lagoon can remain enclosed behind a depositional bar.','bars'),q('dep','c4','Why may a spit fail to cross an estuary?',['River and tidal flow can maintain an opening','Every spit is indestructible','Deposition cannot occur near rivers'],0,'Flow, depth and sediment supply control whether extension continues.','spits')],'coast-deposition'),
make('human-change','People, erosion and coastal flooding',['1.5a','Integrated skill 8: introductory'],[
 ['People alter a coast','Urbanisation adds homes, roads and services near the shore. Farming changes vegetation, drainage and land use. Industry can add ports, reclaimed land and coastal infrastructure. These activities alter landscapes and can change sediment or water pathways. They do not cause every instance of natural coastal erosion.'],
 ['Land loss and inundation','Recession moves the shoreline or cliff inland as land is removed. Coastal flooding covers land with seawater, potentially temporarily; it can damage homes, crops and habitats without removing the whole site. Both can disrupt transport, livelihoods and services. Their effects depend on exposure, vulnerability and management.'],
 ['Whose costs, whose benefits?','A protected town may retain homes and access; changes to sediment supply can affect another frontage. Farmland loss can reduce income; flooding may contaminate soils with salt. Habitat can be damaged or shift as coastlines change. Compare evidence and affected groups rather than assuming the same policy benefits everyone.']
],[['Predict: more homes are built close to a receding cliff. Other things equal…',['More assets may be exposed','Natural erosion must stop','Every home is already flooded'],0],['Compare recession and flooding. Temporary seawater coverage is…',['Flooding','Always complete permanent land removal','Volcanic uplift'],0],['Agriculture can alter a coastal landscape through…',['Drainage and vegetation or field changes','Instant conversion of all clay to chalk','Removing all waves'],0],['A port or defence alters sediment transport. A fair enquiry considers…',['Nearby and downdrift effects as well as local benefits','Only the colour of its buildings','A guarantee that no other place changes'],0]],
[q('people','p1','A cliff retreats and a field edge is removed. This is direct evidence of…',['Coastal recession','Only temporary inundation','New beach growth everywhere'],0,'The land edge has moved inland through loss.','coastal-risk'),q('people','p2','Which human activity may directly alter drainage or vegetation?',['Agriculture','Wave refraction alone','Attrition alone'],0,'Farming can change land cover, boundaries and water movement.','human-coast'),q('people','p3','Why compare different stakeholder groups?',['Benefits and losses can be distributed unequally','Everyone must have identical priorities','Only tourists can be affected'],0,'Residents, farmers, businesses and conservation interests may face different effects.','trade-offs')],
[q('people','c1','Seawater temporarily covers a road that remains after it drains. This demonstrates…',['Flooding without necessarily proving permanent land loss','A new rock family','Proof of no damage'],0,'Inundation and erosion are related hazards but not identical.','coastal-risk'),q('people','c2','Building more infrastructure near an eroding shore can…',['Increase the value or number of exposed assets','Guarantee a safer shore without management','Stop every storm'],0,'Exposure can rise even if the physical process is unchanged.','human-coast'),q('people','c3','Which industry-related change can alter a coastal landscape?',['Port building or land reclamation','Only ice expansion in cracks','Only pebble collisions'],0,'Industrial development can physically reshape a frontage.','human-coast'),q('people','c4','A good account of coastal change should include…',['Effects on people and environments, with evidence','Only a statement that every effect is positive','Only one person’s unsupported opinion'],0,'Explain interactions and unequal outcomes rather than giving a universal verdict.','trade-offs')],'coast-people'),
make('hard-defences','Sea walls, groynes and rock armour',['1.5b'],[
 ['At the sea wall','A sea wall separates land from wave attack and can reduce erosion and flooding at a frontage. Some wall shapes redirect waves; reflected energy can contribute to scour near the base. Walls cost money to build and maintain and do not remove all risk, especially under extreme conditions.'],
 ['Trap or dissipate','Groynes project across a beach and interrupt longshore sediment movement. Sand can accumulate on the updrift side, building a buffer that absorbs energy, but less may reach the downdrift shore. Rip rap or rock armour consists of large blocks: rough surfaces and gaps dissipate wave energy. It occupies space and may affect access and appearance.'],
 ['Choose for a place','A defence must fit the processes, assets, environment and budget. Compare local protection with maintenance, landscape and sediment effects along the coast. Do not call one method universally best: a groyne needs moving sediment and does not create a new sediment supply. Our loop is a mechanism comparison, not a design calculation.']
],[['Predict: a groyne interrupts drift moving right. Sand tends to build on…',['Its left, updrift side','Only its right side in every situation','Neither side because sand disappears'],0],['Compare groyne and rock armour. Rough blocks mainly…',['Dissipate wave energy','Manufacture new sand','Reverse gravity'],0],['A wall protects one frontage but reflects energy. What needs checking?',['Scour and effects around the structure','Only the wall’s paint colour','A guarantee of zero remaining risk'],0],['A downdrift beach gets less sediment. A judgement should…',['Consider this loss alongside local protection','Assume all locations gained equally','Ignore sediment budgets'],0]],
[q('hard','p1','A groyne’s main sediment role is to…',['Interrupt longshore drift','Dissolve every pebble','Raise global sea level'],0,'It can trap moving material locally, with consequences alongshore.','groynes'),q('hard','p2','Why use large irregular blocks as rip rap?',['They dissipate wave energy through roughness and gaps','They guarantee no wave reaches any coast','They make waves only by heating water'],0,'Rough rock armour breaks up and dissipates incoming energy.','rock-armour'),q('hard','p3','Which is a valid limitation of a sea wall?',['Maintenance and possible toe scour','It cannot affect any wave','It always needs no repairs'],0,'Protection has costs and can alter local energy patterns.','seawalls')],
[q('hard','c1','A groyne holds sediment updrift. What is a possible wider effect?',['Reduced supply to downdrift beaches','New sediment is created from nothing','No sediment can ever move again'],0,'Sediment trapped in one place may be unavailable elsewhere.','groynes'),q('hard','c2','Rock armour protects mainly by…',['Dissipating wave energy at the shore','Stopping all tides globally','Changing chalk into granite'],0,'It works on incoming energy, not the global tide.','rock-armour'),q('hard','c3','Why is “a sea wall removes all risk” an overclaim?',['Extreme events, scour and maintenance limitations remain','Every wall is made of sand','A wall has no physical effects'],0,'Risk reduction is conditional, not an absolute guarantee.','seawalls'),q('hard','c4','Which evidence should inform a defence choice?',['Local wave and sediment conditions, assets, costs and environmental effects','Only which structure looks largest','Only another coast’s name'],0,'Management must fit the coast and its objectives.','management-judgement')],'coast-hard'),
make('soft-management','Work with coastal change',['1.5b'],[
 ['Rebuild the buffer','Beach nourishment adds sediment to widen or raise a beach, helping absorb wave energy and supporting amenity. Material can move away again, so monitoring and repeated recharge may be needed. Sediment sourcing, costs and disturbance are trade-offs; a wide beach is not a guarantee against every flood.'],
 ['Make room deliberately','Managed retreat or realignment accepts coastal movement in selected places and may move assets or set defences back. In suitable low-lying areas, controlled inundation can create intertidal habitat and space to absorb energy. It can also mean loss of farmland or other land uses, relocation and difficult compensation decisions.'],
 ['Compare objectives','A town frontage and a less developed coast may justify different approaches. Compare what must be protected, for how long, with whose costs and whose benefits. Planned adaptation involves monitoring and decisions; it is different from claiming change has no consequences. Our examples are conceptual, not permission to flood a named site.']
],[['Predict: sand is added to a narrow beach. It can…',['Provide a larger wave-energy buffer','Permanently eliminate every storm','Automatically turn into bedrock'],0],['Compare initial nourishment and later loss. The practical implication is…',['Monitoring and repeat recharge may be needed','One recharge always lasts forever','Sediment transport has stopped'],0],['A defence is deliberately set back. Which trade-off is plausible?',['Space for intertidal habitat but loss of some existing land use','No person can possibly lose land','Every coast becomes identical'],0],['A fair management judgement compares…',['Objectives, evidence, costs, benefits and affected groups','Only one attractive photograph','Only the highest wall'],0]],
[q('soft','p1','Beach nourishment works by…',['Adding sediment to the beach buffer','Stopping the Moon’s pull','Instantly lowering all sea levels'],0,'A wider or higher sediment beach can absorb more energy.','nourishment'),q('soft','p2','Managed realignment can involve…',['Setting protection back and allowing selected land to change','Guaranteeing no land is affected','Moving all storms offshore'],0,'It deliberately creates space for coastal adjustment, with trade-offs.','realignment'),q('soft','p3','What makes nourishment a continuing commitment?',['Sediment can be transported away and need replacement','Added sand can never move','It repairs every cliff automatically'],0,'Sediment budgets and monitoring determine maintenance needs.','nourishment')],
[q('soft','c1','Which is a possible benefit of realignment in a suitable low-lying site?',['New intertidal habitat and space for water','A guarantee of no land-use conflict','The end of all coastal erosion'],0,'Habitat and flood-space benefits depend on the location and design.','realignment'),q('soft','c2','Which cost should be included in a nourishment appraisal?',['Repeated sediment sourcing and placement','Only the initial photo session','No future cost by definition'],0,'Recharge and environmental impacts can recur.','nourishment'),q('soft','c3','Why might a farmer oppose a realignment scheme?',['It can affect farmland, income and compensation needs','Farmers are never stakeholders','It always creates more identical farmland'],0,'Decision-making must consider those who bear losses.','management-judgement'),q('soft','c4','Which conclusion is best supported?',['Different frontages may need different policies supported by evidence','Soft management has no disadvantages','All coasts must use the same structure'],0,'Context, objectives and distribution of effects matter.','management-judgement')],'coast-soft'),
make('swanage','Swanage Bay and Old Harry Rocks',['1.6a','Integrated skill 7: photo/diagram introduction'],[
 ['Locate the contrasting coast','Swanage Bay lies on the south coast of England in south-east Dorset, facing east. Ballard Down and Old Harry to the north expose Chalk; weaker Wealden sands and clays occur around the bay; Purbeck limestones occur to the south. This broad discordant arrangement helps explain contrasting retreat. Chalk is relatively resistant here, not immune to erosion.'],
 ['Read the photo, explain with sources','The photograph shows pale cliffs and detached rock at Old Harry on 17 October 2013. BGS identifies the rock as Chalk. Water attack exploits weaknesses, with abrasion, hydraulic action, weathering and collapse helping develop erosional forms. A single image supports recognition of features; it cannot establish a retreat rate, exact dates of collapse or today’s condition.'],
 ['A managed bay','At Swanage, the built seafront and beach are important to residents, access and tourism. Published management sources describe sea walls, groynes and periodic nourishment. The Environment Agency’s New Swanage unit N.1 combines maintaining existing defences with limits on their extension and adaptation where needed. Different stretches have different policies: do not treat the whole Dorset coast as one defended line. This is one named example; your school may study another.']
],[['Use the locator. Swanage Bay is in…',['Dorset on England’s south coast','The Scottish Highlands','An inland Welsh valley'],0],['Compare the geology view with the photograph. Old Harry’s rock is…',['Chalk, identified by geological sources','Proved to be granite from colour alone','Unidentifiable even with a source'],0],['Can the 2013 photograph alone show a mean annual retreat rate?',['No: dated comparable positions and elapsed time are needed','Yes: count the white pixels','Yes: every stack retreats at the same rate'],0],['Compare bay management with exposed headland processes. A valid explanation uses…',['Local geology, wave exposure and human decisions together','Only the place name','A rule that every coast has identical defences'],0]],
[q('swanage','p1','Which combination matches this named example?',['East-facing Swanage Bay in Dorset','West-facing Swanage Bay in Scotland','An inland reservoir in Dorset'],0,'Location and orientation help frame wave exposure and connections.','swanage-location'),q('swanage','p2','Which rock-source pairing is supported?',['Old Harry — Chalk, as identified by BGS','Old Harry — granite because every pale rock is granite','All Swanage Bay — identical rock'],0,'A photograph is combined with geological evidence, not colour alone.','swanage-geology'),q('swanage','p3','Why are groynes and nourishment relevant to Swanage?',['They help manage a sediment beach and protect a developed frontage','They prove all cliffs can never erode','They create the Chalk strata'],0,'Human management interacts with the beach sediment system.','swanage-management')],
[q('swanage','c1','The wider coastal form is helped by…',['Contrasting geology and differential erosion','The absence of all geological variation','The claim that Chalk never erodes'],0,'Chalk headland and weaker bay materials respond differently.','swanage-geology'),q('swanage','c2','A detached pale rock in the photograph supports recognition of…',['An erosional stack-like feature','A measured annual erosion rate','A newly built groyne'],0,'The image supports landform observation, while rates require comparable dated measurements.','photo-evidence'),q('swanage','c3','Which management claim is supported by the sources used here?',['Parts of Swanage use existing defences and periodic beach nourishment','Every Dorset stretch has the same policy','A proposed future scheme is necessarily already complete'],0,'Policies and interventions are specific to frontage and date.','swanage-management'),q('swanage','c4','Which makes the strongest explanation of this named coast?',['Connect location, rock contrasts, processes and management with sources','Give only its name and a generic definition','Assume the photograph shows all past and future change'],0,'A named explanation applies mechanisms to verified local evidence.','swanage-synthesis')],'swanage')
];
